document.addEventListener("DOMContentLoaded",()=>{const e={title:document.title,url:window.location.href,text:"Check out this amazing coding academy for kids!"},t=[{name:"WhatsApp",icon:"message-circle",color:"#25D366",url:`https://wa.me/?text=${encodeURIComponent(e.text+" "+e.url)}`},{name:"Twitter",icon:"twitter",color:"#1DA1F2",url:`https://twitter.com/intent/tweet?url=${encodeURIComponent(e.url)}&text=${encodeURIComponent(e.text)}`},{name:"Facebook",icon:"facebook",color:"#1877F2",url:`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(e.url)}`}],n=`\n        \x3c!-- Desktop Sidebar --\x3e\n        <div class="hidden lg:flex fixed left-6 top-1/2 -translate-y-1/2 z-[90] flex-col space-y-4">\n            ${t.map(e=>`\n                <a href="${e.url}" target="_blank" title="Share on ${e.name}"\n                    class="group relative w-12 h-12 bg-white rounded-full shadow-lg flex items-center justify-center border border-gray-100 transition-all hover:scale-110 hover:-translate-y-1">\n                    <i data-lucide="${e.icon}" class="w-5 h-5" style="color: ${e.color}"></i>\n                    <span class="absolute left-16 bg-cosmic-blue text-white text-xs py-1 px-3 rounded opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap">\n                        Share on ${e.name}\n                    </span>\n                </a>\n            `).join("")}\n        </div>\n\n        \x3c!-- Mobile Bottom Bar --\x3e\n        <div class="lg:hidden fixed bottom-6 right-6 z-[90] flex flex-col space-y-3 items-end">\n             <button id="mobile-share-toggle" class="w-14 h-14 bg-supernova-orange text-white rounded-full shadow-2xl flex items-center justify-center transform active:scale-95 transition-all">\n                <i data-lucide="share-2" class="w-6 h-6"></i>\n             </button>\n             <div id="mobile-share-menu" class="hidden flex flex-col space-y-3 mb-2">\n                ${t.map(e=>`\n                    <a href="${e.url}" target="_blank" \n                        class="w-12 h-12 bg-white rounded-full shadow-xl flex items-center justify-center border border-gray-100 transform translate-y-10 opacity-0 transition-all">\n                        <i data-lucide="${e.icon}" class="w-5 h-5" style="color: ${e.color}"></i>\n                    </a>\n                `).reverse().join("")}\n             </div>\n        </div>\n    `;document.body.insertAdjacentHTML("beforeend",n),lucide.createIcons();const o=document.getElementById("mobile-share-toggle"),a=document.getElementById("mobile-share-menu"),s=a.querySelectorAll("a");let l=!1;o&&o.addEventListener("click",()=>{l=!l,l?(a.classList.remove("hidden"),o.classList.add("rotate-45"),s.forEach((e,t)=>{setTimeout(()=>{e.classList.remove("translate-y-10","opacity-0"),e.classList.add("translate-y-0","opacity-100")},100*t)})):(o.classList.remove("rotate-45"),s.forEach((e,t)=>{e.classList.add("translate-y-10","opacity-0"),e.classList.remove("translate-y-0","opacity-100")}),setTimeout(()=>a.classList.add("hidden"),300))})});